B.awI=s(["Hold still. This salve stings.","Another one from the east. The wounds are deep.","Drink first. Then tell me what you saw out there."],t.s)
B.aOe=new A.et("healer","Healer Mira","village_healer",4,3,12,B.awI,null,null,null,null,!0,!1,!1,!0,null,"priest",null,null,"healer",null)
B.aug=s(["Are you a warrior? Mum says orcs eat children.","I drew an orc. It is very ugly.","Uncle says the orcs will come back this year."],t.s)
B.aOc=new A.et("child","Tali","village_family",9,3,12,B.aug,null,null,null,null,!0,!1,!1,!1,null,"adventurer",null,null,"child",null)
B.amC=s(["The deer ran east. Strange for deer.","Watch the tree line when you go out.","My bow is strung. Always."],t.s)
B.aO4=new A.et("hunter","Hunter Dahk","village",20,15,12,B.amC,null,null,null,null,!0,!1,!1,!1,null,"archer",null,null,"hunter",null)
B.au7=s(["I remember when the east was only forest.","Fire keeps the bad things away. Mostly."],t.s)
B.aO3=new A.et("elder","Elder Sohn","village",31,34,12,B.au7,null,null,null,null,!0,!1,!1,!1,null,"mage",null,null,"marl","sohn_scene")
B.aB8=s(["Sit, sit! Best salve in the world, this.","Two more weeks and I am back out there."],t.s)
